  "chk_o4_w": "உள்ளே இருக்கும் ஸ்பீக்கர் மூலம் டெலிவரி ஆட்களுக்கு வழி சொல்லவோ சந்தேக நபர்களை எச்சரிக்கவோ போனிலிருந்தே பேசலாம்.",
