  "city_hero_desc_install": "{city} பகுதியில் அசல் {brand} CCTV கேமராக்களுடன் உங்கள் வீடு அல்லது கடையை பாதுகாப்பாக வையுங்கள். 2 நிமிடத்தில் தெளிவான கொட்டேஷன் பெறுங்கள்.",
