  "faq_s_a1": "ஆமாம். எல்லா TEAM CCTV Quote-களிலும் 18% GST உட்படத்தான் — மறைமுக கட்டணம் எதுவுமில்லை. Camera, DVR/NVR, கேபிள் மற்றும் முழு Fitting-உம் இதில் அடங்கும்.",
  "faq_s_a2": "ஆமாம். ஒவ்வொரு Quote-லும் Camera பொருத்துதல், நேர்த்தியான வயரிங், DVR/NVR செட்டப், போன் App இணைப்பு மற்றும் முழு டெமோ அடங்கும்.",
  "faq_s_a3": "முழு 4-Camera செட்டப் பிராண்ட் மற்றும் மாடலைப் பொறுத்து சுமார் ₹14,200 முதல் ₹18,000 வரை தொடங்குகிறது. 18% GST, கேபிள், Fitting எல்லாம் உட்பட.",
  "faq_s_a4": "ஆமாம். CP Plus மற்றும் Prama மாடல்கள் BIS-ER சான்றிதழ் கொண்டவை — வீடு, கடை, சொசைட்டி மற்றும் அரசு டெண்டர்களுக்கு ஏற்றது. STQC மாடல்களும் உள்ளன.",
