  "land_step1_desc": "தேவையான கேமராக்களைத் தேர்ந்தெடுத்து CP Plus, Hikvision அல்லது Prama விலை மற்றும் மாத EMI பாருங்கள்.",
  "land_step1_title": "கேமராக்களைத் தேர்ந்தெடுத்து ஒப்பிடுங்க",
  "land_step2_desc": "₹500 மட்டும் கட்டி விலையையும் தேதியையும் உறுதி செய்யுங்கள். மீதி தொகையை பொருட்கள் வந்து சரிபார்த்த பிறகு கொடுங்கள்.",
  "land_step2_title": "₹500 டோக்கனுடன் புக் பண்ணுங்க அல்லது இலவச விசிட் எடுங்க",
  "land_step3_desc": "எங்கள் சரிபார்க்கப்பட்ட டெக்னீஷியன் நேர்த்தியாக வயரிங் செய்து, கேமரா & DVR/NVR பொருத்தி உங்கள் போனில் லைவ் வியூ செட் பண்ணி தருவார்.",
  "land_step3_title": "சிறந்த ஃபிட்டிங் & மொபைல் லைவ் வியூ",
  "land_step_prefix": "படி",
  "land_steps_heading": "ஆன்லைன் கொட்டேஷன் முதல் போனில் நேரலை கேமரா வரை",
  "landing_areas_all": "+ சுத்தி இருக்குற எல்லா ஏரியாக்களும்",
  "landing_areas_desc": "எங்க இன்ஸ்டாலேஷன் டீம் டெய்லி சிட்டி முழுக்க போறாங்க. எல்லா மெயின் ரெசிடென்ஷியல், கமர்ஷியல் ஏரியாக்களுக்கும் நாங்க சீக்கிரமா சர்வீஸ் & மெயின்டனன்ஸ் தரோம்.",
  "landing_areas_title": "{city}-ல நாங்க சர்வீஸ் பண்ற ஏரியாக்கள்",
  "landing_call_support": "சப்போர்ட்டிற்கு கால் செய்யுங்கள்",
  "landing_commercial_desc": "{commercialAreas}-ல இருக்குற ஆபீஸ், குடோன் மற்றும் ஃபேக்டரிகளுக்கு சூப்பர். மொபைல் லைவ் வியூ மற்றும் புரொபஷனல் செட்டப் உடன் ஹை-டெஃபனிஷன் IP கேமராக்கள்.",
  "landing_commercial_tag": "கமர்ஷியல்",
  "landing_commercial_title": "8 முதல் 16-கேமரா நெட்வொர்க்ஸ்",
  "landing_custom_setup": "விருப்பப்படி அமைக்கவும் →",
  "landing_exact_quote": "உடனே விலை பாருங்கள் →",
  "landing_final_cta_desc": "2 நிமிடத்தில் சரியான கொட்டேஷன் வாங்குங்க. 18% GST பில் உண்டு. எந்த மறைமுக கட்டணமும் இல்லை.",
  "landing_final_cta_title": "உங்க {city} ப்ராப்பர்ட்டியை இன்னைக்கே பாதுகாக்குங்க.",
