  "landing_pricing_title": "{city}-ல {brand} CCTV இன்ஸ்டாலேஷன் செலவு",
  "landing_residential_desc": "வீடு மற்றும் சின்ன கடைகளுக்கு சிறந்தது. இதில் {brand} கேமராக்கள், 4-சேனல் DVR, வயரிங் மற்றும் நேரடி ஃபிட்டிங் அடங்கும்.",
