  "legal_full_notice": "முழுமையான சட்ட விவரங்கள் கீழே ஆங்கிலத்தில் உள்ளன.",
  "legal_privacy_body": "உங்கள் CCTV கொட்டேஷன் தயாரிக்கவும், இன்ஸ்டாலேஷன் புக் செய்யவும், 18% GST வாரண்டி பில் வழங்கவும் மட்டுமே உங்கள் பெயர், மொபைல் எண், பின்கோடு மற்றும் இட விவரங்களைப் பெறுகிறோம். உங்கள் டேட்டாவை நாங்கள் ஒருபோதும் விற்பதில்லை. மாற்ற அல்லது நீக்க hello@cctvquotation.com-க்கு ஈமெயில் செய்யவும்.",
  "legal_privacy_title": "தனியுரிமைக் கொள்கை — முக்கிய அம்சங்கள்",
  "legal_terms_body": "கொட்டேஷனில் 18% GST, ஒரிஜினல் சீல் செய்த ஹார்டுவேர் மற்றும் ஸ்டாண்டர்ட் கேபிள் (15மீ/கேமரா) அடங்கும். கட்டண நிலைகள்: ₹500 புக்கிங் டோக்கன், பொருள் டெலிவரியில் 90%, மொபைல் லைவ் டெஸ்டிங்கிற்குப் பிறகு 10%. ஹார்டுவேர் பிராண்ட் வாரண்டி மற்றும் 1 வருட சர்வீஸ் சப்போர்ட் உண்டு.",
  "legal_terms_title": "சேவை விதிமுறைகள் — முக்கிய அம்சங்கள்",
