  "pb_hyb_cbl_d": "கீழே உள்ள கேபிள்கள் உங்கள் {wired} வயர் கேமராக்களுக்கு மட்டுமே. {wireless} வயர்லெஸ் கேமராக்களுக்கு வீடியோ கேபிள் தேவையில்லை.",
