  "pb_no_rec_req_d": "உங்கள் Wi-Fi & 4G கேமராக்கள் நேரடியாக Wi-Fi ரவுட்டர் அல்லது SIM மூலம் இணையும். MicroSD கார்டில் பதிவாகி எங்கிருந்தும் மொபைலில் பார்க்கலாம்.",
