  "pb_opt_nvr_d": "வயர்லெஸ் கேமராக்கள் நேரடியாக MicroSD கார்டில் ரெக்கார்ட் ஆகி போன் ஆப்பில் தெரியும். 24/7 தொடர் ரெக்கார்டிங் அல்லது TV-யில் பார்க்க மட்டுமே NVR ஆப்ஷனல்.",
