  "pb_pwr_inc_d": "ஒவ்வொரு Wi-Fi & 4G கேமரா பாக்ஸிலும் 12V/5V பவர் அடாப்டர் (அல்லது பேட்டரி/சோலார்) உள்ளது. தனி SMPS பாக்ஸ் அல்லது PoE சுவிட்ச் தேவையில்லை!",
