  "pb_wf_cbl_badge": "100% வயர் இல்லாத வீடியோ",
  "pb_wf_cbl_d": "வயர்லெஸ் கேமராக்களுக்கு 3+1 அல்லது CAT6 கேபிள் தேவையில்லை. அருகில் பவர் சாக்கெட் இல்லையென்றால் கீழே உள்ள 2-கோர் பவர் வயரைச் சேர்க்கவும்.",
  "pb_wf_cbl_t": "வீடியோ கேபிள் தேவையில்லை (வயர்லெஸ் Wi-Fi / 4G)",
  "pb_wf_cbl_tip_d": "வயர்லெஸ் கேமராக்கள் Wi-Fi அல்லது 4G வழியே இயங்கும், பவர் அடாப்டர் பாக்ஸில் உள்ளது. NVR-ஐ TV-யில் இணைக்க HDMI கேபிள் தேவைப்பட்டால் எடுங்கள், இல்லையேல் அடுத்த படிக்குச் செல்லுங்கள்.",
  "pb_wf_desc": "வீடியோ கேபிள் தேவையில்லை. வீடு, கடை மற்றும் மொபைல் ஆப்பில் பார்க்க மிக எளிது.",
  "pb_wf_f1": "தனி MicroSD ஸ்டோரேஜ்",
  "pb_wf_f2": "நேரடி ஆப் அல்லது NVR உடன் இயங்கும்",
  "pb_wf_f3": "Wi-Fi / 4G SIM இணைப்பு",
