  "pb_wf_title": "வயர்லெஸ் (Wi-Fi / 4G)",
  "pb_why_wf_d": "வயர் கொண்டு செல்ல கடினமான இடங்களுக்கு (கேட், மாடி, தோட்டம்) சிறந்தது. இவை MicroSD கார்டில் ரெக்கார்ட் செய்யும் மற்றும் {tech} ரெக்கார்டர் போர்ட்டைப் பயன்படுத்தாது.",
  "pb_why_wf_t": "வயர் செட்டப்பில் வயர்லெஸ் கேமராக்களை ஏன் சேர்க்க வேண்டும்? ",
